// #6a993d795019333734edc22d (#edc22d) AC1/AC2 — «תפקיד איש הקשר» обязателен (реджект 05.10 Р1): всё заполнено, кроме него → сохранение заблокировано (кейс BIZ-LC-002).
// spec: specs/business-lifecycle.md (3.2) · seed: tests/seed.admin.spec.ts
// @prod-safe: бизнес не создаётся. Страховка — запрос admin-create-business перехватывается и обрывается (и должен не случиться вовсе).
import * as path from 'path';
import { test, expect } from '../../fixtures';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

test.describe('Создание бизнеса Super Admin — обязательные поля (#6a993d795019333734edc22d)', () => {
  test('всё заполнено, кроме «תפקיד איש הקשר» → сохранение заблокировано @desktop @prod-safe #6a993d795019333734edc22d', async ({ page }) => {
    let createCalls = 0;
    await page.route('**/functions/v1/admin-create-business', (route) => {
      createCalls++;
      return route.abort();
    });

    await page.goto('/admin/businesses/new');
    await expect(page.getByRole('heading', { level: 1, name: 'יצירת בית עסק' })).toBeVisible();

    const biz = page.getByRole('group', { name: 'פרטי העסק' });
    const contact = page.getByRole('group', { name: 'איש קשר' });
    const manager = page.getByRole('group', { name: 'מנהל/ת החשבון הראשון/ה' });
    const filled = [
      [biz.getByRole('textbox', { name: 'שם העסק (חובה)' }), 'QA-AUTO role-missing'],
      [biz.getByRole('textbox', { name: 'תחום פעילות (חובה)' }), 'QA-AUTO'],
      [contact.getByRole('textbox', { name: 'שם איש הקשר (חובה)' }), 'QA-AUTO איש קשר'],
      [contact.getByRole('textbox', { name: 'טלפון (חובה)' }), '0500000000'],
      [contact.getByRole('textbox', { name: 'מייל (חובה)' }), 'qa+auto-role@example.com'],
      [manager.getByRole('textbox', { name: 'שם מלא (חובה)' }), 'QA-AUTO מנהל'],
      [manager.getByRole('textbox', { name: 'מייל (חובה)' }), 'qa+auto-role-mgr@example.com'],
    ] as const;
    for (const [field, value] of filled) await field.fill(value);
    const role = contact.getByRole('textbox', { name: 'תפקיד איש הקשר (חובה)' });
    await expect(role).toHaveValue('');

    await page.getByRole('button', { name: 'יצירת בית העסק' }).click();

    // AC1 «שם ותפקיד איש הקשר» обязательны → AC2: подсвечено только пустое поле роли.
    await expect(page.getByRole('alert').filter({ hasText: 'לא ניתן לשמור' })).toBeVisible();
    await expect(role).toHaveAttribute('aria-invalid', 'true');
    await expect(role).toHaveAccessibleDescription('יש להזין את תפקיד איש הקשר');

    // Остальные поля без ошибки и со своими значениями.
    for (const [field, value] of filled) {
      await expect(field, value).toHaveValue(value);
      await expect(field, value).not.toHaveAttribute('aria-invalid', 'true');
    }

    await expect(page).toHaveURL(/\/admin\/businesses\/new$/);
    expect(createCalls, 'admin-create-business не вызывается').toBe(0);
  });
});
